function recipeSubscription({ body }) {
  const message = body?.message,
    chatId = message?.chat?.id,
    name = message?.from?.first_name;
  if (!Number.isSafeInteger(chatId) || chatId === 0 || typeof name !== "string" || !name.trim())
    throw new Error("A message with a valid chat ID and sender first name is required.");
  return { chatId, name, filterByFormula: "{chatid} = " + chatId };
}

return $input.all().map((item, index) => ({
  json: recipeSubscription({ body: item.json }),
  pairedItem: { item: index },
}));

function recipePlan({ chatId, name, records }) {
  if (!Array.isArray(records) || records.length > 1)
    throw new Error("Airtable lookup must return at most one matching subscriber.");
  if (records.length && (!records[0]?.id || Number(records[0]?.fields?.chatid) !== chatId))
    throw new Error("Airtable lookup returned another chat.");
  return {
    plan: { mode: "subscription", recipients: [{ chatId }], isNew: records.length === 0, name },
  };
}

const identity = $("Read Subscriber Identity").first().json;
return [
  {
    json: recipePlan({
      ...identity,
      records: $input
        .all()
        .map((i) => i.json)
        .filter((r) => r.id),
    }),
  },
];

function collectRecipes({ plan, previousState, body, statusCode, bodyEncoding = "json", welcome }) {
  const state = previousState
    ? { index: previousState.index, recipes: [...previousState.recipes] }
    : { index: 0, recipes: [] };
  if (!previousState && plan.mode === "subscription") {
    const receipt = welcome;
    if (
      !Number.isInteger(receipt?.messageId) ||
      receipt.messageId < 1 ||
      receipt.chat?.id !== plan.recipients[0]?.chatId
    )
      throw new Error("Welcome receipt does not match the subscription chat.");
  }
  if (previousState) {
    if (statusCode < 200 || statusCode >= 300 || bodyEncoding !== "json")
      throw new Error("Recipe request did not return successful JSON.");
    const recipe = body?.recipes?.[0],
      url = (value) =>
        typeof value === "string" &&
        /^https?:\/\/[^/?#\s@]+(?:[/?#]|$)/i.test(value) &&
        !/[\s]/.test(value);
    if (
      !recipe ||
      typeof recipe.title !== "string" ||
      !recipe.title.trim() ||
      !url(recipe.image) ||
      !url(recipe.sourceUrl)
    )
      throw new Error("A recipe needs a title, image URL and source URL.");
    const text = "\n" + recipe.title + "\n\n" + recipe.sourceUrl;
    if (text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").length > 4096)
      throw new Error("Recipe title and URL exceed the Telegram message limit.");
    const recipient = plan.recipients[state.index];
    if (!recipient) throw new Error("Recipe count exceeds recipient count.");
    state.recipes.push({ ...recipient, image: recipe.image, text });
    state.index++;
  }
  return { state, isNew: plan.isNew, more: state.index < plan.recipients.length };
}

const plan = $("Plan First Recipe and Registration").first().json.plan,
  w = $("Welcome the Chat").first().json;
collectRecipes({
  plan,
  previousState: null,
  welcome: { messageId: w.result?.message_id, chat: w.result?.chat },
});
const state = collectRecipes({
  plan,
  previousState: { index: 0, recipes: [] },
  body: $input.first().json,
  statusCode: 200,
  bodyEncoding: "json",
}).state;
return [{ json: state.recipes[0] }];

function collectRecipePhotos({ plan, recipes, previousState, messageId, chat, error }) {
  const state = previousState
    ? { index: previousState.index, receipts: [...previousState.receipts] }
    : { index: 0, receipts: [] };
  if (previousState) {
    const expected = recipes[state.index],
      invalid = !Number.isInteger(messageId) || messageId < 1 || chat?.id !== expected?.chatId,
      problem =
        error?.message ?? (invalid ? "Recipe photo receipt does not match the recipient." : null);
    if (problem) {
      if (plan.mode !== "daily") throw new Error(problem);
      state.receipts.push({ chatId: expected.chatId, status: "failed", error: problem });
    } else state.receipts.push({ chatId: expected.chatId, status: "sent", messageId });
    state.index++;
  }
  const next = recipes[state.index];
  return {
    state,
    more: !!next,
    chatId: next?.chatId ?? 0,
    photo: next?.image ?? "https://example.com/unused.jpg",
  };
}

const recipes = $("Validate First Recipe")
    .all()
    .map((i) => i.json),
  items = $input.all();
if (items.length !== recipes.length) throw Error("Photo receipt count differs.");
let state = { index: 0, receipts: [] };
for (const item of items)
  state = collectRecipePhotos({
    plan: { mode: "subscription" },
    recipes,
    previousState: state,
    messageId: item.json.result?.message_id,
    chat: item.json.result?.chat,
    error: item.json.error ? { message: item.json.error } : null,
  }).state;
return recipes.map((json, index) => ({ json, pairedItem: { item: index } }));

const p = $("Plan First Recipe and Registration").first().json.plan,
  r = $input.first().json;
if (!r.id || Number(r.fields?.chatid) !== p.recipients[0].chatId || r.fields?.Name !== p.name)
  throw Error("Subscriber receipt differs.");
return [{ json: $("Validate First Recipe").first().json }];

const expected = $("Validate First Recipe").all(),
  items = $input.all();
if (items.length !== expected.length) throw Error("Link receipt count differs.");
return items.map((item, index) => {
  const e = expected[index].json,
    r = item.json.result;
  if (item.json.error && false) return item;
  if (
    !Number.isInteger(r?.message_id) ||
    r.message_id < 1 ||
    r.chat?.id !== e.chatId ||
    r.text !== e.text
  ) {
    throw Error("Recipe link receipt differs.");
  }
  return item;
});

function collectSubscribers({ previousState, records, offset }) {
  const state = previousState
    ? {
        ...previousState,
        recipients: [...previousState.recipients],
        cursors: [...previousState.cursors],
      }
    : { recipients: [], cursors: [] };
  if (previousState) {
    if (!Array.isArray(records)) throw new Error("Airtable returned no record list.");
    for (const record of records) {
      const raw = record?.fields?.chatid,
        id = typeof raw === "string" && /^-?\d+$/.test(raw) ? Number(raw) : raw;
      if (!record?.id || !Number.isSafeInteger(id) || id === 0)
        throw new Error("Each subscriber needs a record ID and safe numeric chatid.");
      state.recipients.push({ recordId: record.id, chatId: id });
    }
    if (offset !== null && offset !== undefined && (typeof offset !== "string" || !offset))
      throw new Error("Invalid Airtable pagination cursor.");
    if (offset) {
      if (state.cursors.includes(offset))
        throw new Error("Airtable repeated its pagination cursor.");
      state.cursors.push(offset);
    }
  }
  const more = !previousState || !!offset;
  return {
    state,
    more,
    offset: more ? (offset ?? null) : null,
    plan: { mode: "daily", recipients: state.recipients, isNew: false, name: "" },
  };
}

function uniqueSubscribers(input) {
  const result = collectSubscribers(input);
  const chats = new Set();
  result.state.recipients = result.state.recipients.filter(({ chatId }) => {
    if (chats.has(chatId)) return false;
    chats.add(chatId);
    return true;
  });
  result.plan.recipients = result.state.recipients;
  return result;
}

const records = $input.all().map((item) => item.json);
return uniqueSubscribers({
  previousState: { recipients: [], cursors: [] },
  records,
  offset: null,
}).plan.recipients.map((json) => ({ json }));

