function n8nDelivery(item, chatId, text) {
  const incoming = item.json;
  const record = incoming?.result;
  if (
    incoming?.error ||
    !Number.isSafeInteger(record?.message_id) ||
    record.message_id < 1 ||
    record.chat?.id !== chatId ||
    (text !== undefined && record.text !== text)
  ) {
    return { chatId, status: "unconfirmed", reason: "Telegram did not confirm the message" };
  }
  return { chatId, status: "sent", messageId: record.message_id };
}

